import{af as e,z as a,J as r,ab as i}from"./chunks/framework.C1QHhBQn.js";const o="/docs/pr/40/images/devices/general/led-vehicle-status.svg",u=JSON.parse('{"title":"Vehicle (VT3) LED indicators","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"guides/vehicle-leds.md","filePath":"guides/vehicle-leds.md"}'),n={name:"guides/vehicle-leds.md"};function s(d,t,h,l,c,p){return a(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...t[0]||(t[0]=[i('<h1 id="vehicle-vt3-led-indicators" tabindex="-1">Vehicle (VT3) LED indicators <a class="header-anchor" href="#vehicle-vt3-led-indicators" aria-label="Permalink to &quot;Vehicle (VT3) LED indicators&quot;">​</a></h1><p>This guide covers <strong>Vehicle VT3, device ID prefix 40</strong>, using the standard four-indicator firmware display. It does not describe the older <a href="/docs/pr/40/devices/history/VT2">Vehicle VT2</a> or the RGB display on an RH2 handheld.</p><h2 id="normal-battery-display" tabindex="-1">Normal battery display <a class="header-anchor" href="#normal-battery-display" aria-label="Permalink to &quot;Normal battery display&quot;">​</a></h2><p>A short status-button press normally shows the battery level briefly. The four indicators use these approximate bands:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Normal battery display</th></tr></thead><tbody><tr><td>Below 20%</td><td>First indicator flashes when showing status off charge</td></tr><tr><td>20% to below 40%</td><td>1 indicator</td></tr><tr><td>40% to below 60%</td><td>2 indicators</td></tr><tr><td>60% to below 80%</td><td>3 indicators</td></tr><tr><td>80% or more</td><td>4 indicators</td></tr></tbody></table><p>These bands apply to the normal battery display only. Startup, alerts and application-controlled patterns can use the same lights for a different reason. Four lights are not an exact 100% reading.</p><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><ul><li>Below about 95%, the highest lit battery indicator blinks, roughly one second on and one second off. At very low charge, the first indicator blinks.</li><li>At about 95% or above, the normal charging display becomes steady. This means a high charge level, not an exact 100% reading.</li><li>When unplugged and resting, the lights normally go out after any temporary status display finishes. A button press, startup or other activity can still light them.</li></ul><p>These are the standard battery-bar patterns. They are not the RGB charging colours used by RH2.</p><p>The vehicle connection display below temporarily uses the same indicators for a different purpose. There is no universal blue-light check for VT3 installation: use the matching pattern and the reported power/ignition state.</p><h2 id="vehicle-connection-status" tabindex="-1">Vehicle connection status <a class="header-anchor" href="#vehicle-connection-status" aria-label="Permalink to &quot;Vehicle connection status&quot;">​</a></h2><p>After showing battery status, a short status-button press shows ignition and charging information in <strong>five brief flash cycles</strong>, about 0.3 seconds on and 0.2 seconds off:</p><table tabindex="0"><thead><tr><th>Indicator pair</th><th>Flashes when</th></tr></thead><tbody><tr><td>1 and 2</td><td>The device detects ignition high</td></tr><tr><td>3 and 4</td><td>The device reports that it is charging</td></tr></tbody></table><p>Both pairs can flash when both conditions are true. These are logical indicator numbers, not a left-to-right enclosure diagram. The diagram below does not assert the physical colour or orientation for a hardware revision.</p><figure><img src="'+o+'" alt="Vehicle connection pattern: indicators 1 and 2 flash for ignition high, indicators 3 and 4 for charging, and all four for both. Five cycles, about 0.3 seconds on and 0.2 seconds off. Neutral shading indicates on and is not an LED colour." tabindex="0"><figcaption>Vehicle connection pattern: indicators 1 and 2 flash for ignition high, indicators 3 and 4 for charging, and all four for both. Five cycles, about 0.3 seconds on and 0.2 seconds off. Neutral shading indicates on and is not an LED colour.</figcaption></figure><p>The display can also appear when charging starts or ignition becomes high. Paired flashing can therefore be normal. External power does not always mean the battery is currently charging, so an unlit charging pair alone is not proof of a wiring fault.</p><p>Follow the <a href="/docs/pr/40/devices/vehicle/installation#step-8-check-functionality">installation checks</a> and confirm the reported external-power and ignition state where available. If those readings do not match the wiring, ask support before changing the installation.</p><h2 id="startup-and-other-patterns" tabindex="-1">Startup and other patterns <a class="header-anchor" href="#startup-and-other-patterns" aria-label="Permalink to &quot;Startup and other patterns&quot;">​</a></h2><p>Startup, alarms and custom applications can use the same four lights. Wait for startup to finish and check the latest successful communication in the app or portal. Do not interpret an unfamiliar pattern as a battery level or as the Pro3 charger-protection pattern.</p><p>For another product, use the <a href="/docs/pr/40/guides/leds">LED guide by model</a>. For persistent unexpected behaviour, send <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">support</a> the device ID, hardware revision if known, power/ignition state and a short video.</p>',20)])])}const f=e(n,[["render",s]]);export{u as __pageData,f as default};
